import org.apache.poi.ss.usermodel.*;
import org.apache.poi.xssf.usermodel.XSSFWorkbook;

import java.io.FileInputStream;
import java.util.ArrayList;
import java.util.List;

public class ExcelReader {
    public static void main(String[] args) throws Exception {
        Workbook workbook = new XSSFWorkbook(new FileInputStream("magnetic-field.xlsx"));
        Sheet sheet = workbook.getSheet("Data"); // assuming your data is in a sheet named "Data"
        List<MagneticField> fields = new ArrayList<>();

        int rowIndex = 1; // starting from row 1
        while (rowIndex <= sheet.getLastRowNum()) {
            Row row = sheet.getRow(rowIndex);
            String location = row.getCell(0).toString();
            double latitude = row.getCell(1).getNumericCellValue();
            double longitude = row.getCell(2).getNumericCellValue();
            double magneticFieldIntensity = row.getCell(3).getNumericCellValue();
            MagneticField field = new MagneticField(location, latitude, longitude, magneticFieldIntensity);
            fields.add(field);
            rowIndex++;
        }
        System.out.println("Fields read: " + fields);
        workbook.close();
    }
}
```

