```jsx
import React, { useState, useEffect } from 'react';
import { observer } from 'mobx-react';
import { CreateObjectModel } from './CreateObjectModel';
import styles from './CreateObjectView.module.css';

const CreateObjectView = observer(({ model }) => {
  const [asset, setAsset] = useState('');

  useEffect(() => {
    model.loadAvailableAssets();
  }, []);

  const handleAssetChange = event => {
    setAsset(event.target.value);
  };

  const handleCreateObject = () => {
    if (asset) {
      model.createObject(asset).then(() => {
        model.setSelectedAsset(asset);
      });
    }
  };

  const handleCleanupScene = () => {
    model.cleanupScene();
  };

  const availableAssets = model.availableAssets;

  return (
    <div className={styles.CreateObjectView}>
      <label htmlFor="asset">Asset:</label>
      <input type="text" id="asset" value={asset} onChange={handleAssetChange} />
      <button id="create-object" onClick={handleCreateObject}>Create object</button>
      {availableAssets && availableAssets.length > 0 && (
        <ul id="available-assets">
          {availableAssets.map(asset => (
            <li key={asset}>{asset}</li>
          ))}
        </ul>
      )}
      <button id="cleanup-scene" onClick={handleCleanupScene}>Cleanup scene</button>
    </div>
  );
});

export default CreateObjectView;

// CSS module for styling
const styles = {
  CreateObjectView: 'CreateObjectView',
};
```

