To address this challenge, we will create a dictionary of commonly confused homophones and their correct spellings. Then, we will iterate through the input passage, replacing any words that match the keys in our dictionary with their corresponding values from the dictionary. Here's how you could implement this solution in Swift:

```swift
let homophoneDictionary = [
    "there": "their",
    "they're": "they are",
    "too": ["to", "two"] // Multiple values for one key, indicating multiple correct spellings
]

func replaceHomophones(_ text: String) -> String {
    var result = ""

    for word in text.components(separatedBy: .whitespacesAndNewlines) {
        let lowercasedWord = word.lowercased()

        for (key, value) in homophoneDictionary {
            if Set(key.lowercased().unicodeScalars).isSubset(of: Set(word.lowercased().unicodeScalars)) {
                result += value + " "
                break
            } else if Array(key.lowercased()) == Array(word.lowercased()), let arrayValue = homophoneDictionary[key] as? [String], !arrayValue.isEmpty {
                result += arrayValue[Int.random(in: 0..<arrayValue.count)] + " "
                break
            }
        }

        if !result.isEmpty {
            result.removeLastSpace()
        }
        result += "\(word) "
    }

    return result
}

