function findNestedKeys(obj, keyPath) {
  let result = [];

  const keys = keyPath.split('.');
  const length = keys.length;
  let currentObj = obj;

  for (let I = 0; I < length; i++) {
    const key = keys[i];

    if (!currentObj.hasOwnProperty(key)) {
      // If any key is missing, return empty array
      return result;
    }

    const val = currentObj[key];

    // Add all entries of the current object to result
    // Note that this assumes that all values are arrays or objects with entries
    // If you want to exclude some types, add more checks here
    result = result.concat(Array.isArray(val) ? val : Object.entries(val));

    // Move to next level of nesting
    currentObj = Array.isArray(val) ? val : val[key];
  }

  // Return final result
  return result;
}

